-- Re-imports the 15 activity_templates rows previously seeded into
-- app_config (20260921200000_import_activity_templates.sql) into the real
-- table created by 20260922100000. Ids are regenerated via the same
-- deterministic uuid5(NS, 'actype_' + old_id) scheme used for
-- boats/locations/daily_log/etc — NS = 6f6e7972-6d69-4c75-6231-000000000001,
-- prefix 'actype_'. reservedBoatIds/requiredEndorsement values are left
-- as-is: boat ids were already real Supabase uuids, and cert ids
-- (certDefs) aren't being remapped in this migration.

-- The app_config blob is now dead weight — every read/write path is
-- rewritten against the real table (this migration + 20260922100000 +
-- _shared/config.ts + save-volunteer-event). Remove it so nothing can
-- accidentally read stale data from it.
delete from public.app_config where key = 'activity_templates';
